import fishDataJson from "./fishmb-fish-data.json";

/**
 * Data behind the Fish tab (/fishmb/fish) and the species guide pages
 * (/fishmb/species/<slug>). Generated by scripts/build-fishmb-fish-data.mjs
 * from FishMB's own lake catalogue (species set, lake counts) and the
 * Bump Board researched fishing library (full guides, scientific names,
 * Manitoba Master Angler minimums). A species with guideId null has no
 * guide in that library — pages say so instead of filling the space.
 */

export interface FishGuideBlock {
  heading: string;
  lines: string[];
}
export interface FishGuideTechniqueSeason {
  heading: string;
  groups: { label: string; lines: string[] }[];
}
export interface FishGuide {
  about: string[];
  hasLibrary: boolean;
  techniques: FishGuideTechniqueSeason[];
  movementSeasons: FishGuideBlock[];
  movementDaily: FishGuideBlock[];
  weatherFacts: string[];
  weatherOverlays: FishGuideBlock[];
  weatherNotCounted: { factor: string; reason: string }[];
  spawningSeasons: FishGuideBlock[];
  spawningSources: { factor: string; citation: string }[];
}

export interface FishSpecies {
  name: string;
  slug: string;
  guideId: string | null;
  scientific: string | null;
  maMin: string | null;
  lakeCount: number;
  pinnedCount: number;
}

interface FishDataFile {
  species: FishSpecies[];
  guides: Record<string, FishGuide>;
}

const DATA = fishDataJson as unknown as FishDataFile;

export function getFishSpecies(): FishSpecies[] {
  return DATA.species;
}

export function getFishSpeciesBySlug(slug: string): FishSpecies | null {
  return DATA.species.find((s) => s.slug === slug) ?? null;
}

export function getFishGuide(species: FishSpecies): FishGuide | null {
  if (!species.guideId) return null;
  return DATA.guides[species.guideId] ?? null;
}
